<?php require_once __DIR__.'/includes/bootstrap.php';require_role(['admin','librarian']);$from=$_GET['from']??'';$to=$_GET['to']??'';$status=$_GET['status']??'';$sql='SELECT br.*,u.full_name,b.title FROM borrowings br JOIN users u ON u.id=br.user_id JOIN books b ON b.id=br.book_id WHERE 1=1';$types='';$p=[];if($from&&preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$from)){$sql.=' AND DATE(br.requested_at)>=?';$types.='s';$p[]=$from;}if($to&&preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$to)){$sql.=' AND DATE(br.requested_at)<=?';$types.='s';$p[]=$to;}if(in_array($status,['pending','approved','borrowed','returned','rejected'],true)){$sql.=' AND br.status=?';$types.='s';$p[]=$status;}$sql.=' ORDER BY br.requested_at DESC';$s=$conn->prepare($sql);if($types)$s->bind_param($types,...$p);$s->execute();$rows=$s->get_result();page_header('Reports');?><div class="page-heading no-print"><div><p class="eyebrow">INFORMATION MANAGEMENT</p><h1>Borrowing report</h1></div><button class="btn" onclick="window.print()">Print report</button></div><form class="filter-bar no-print"><div><label>From</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>To</label><input type="date" name="to" value="<?=e($to)?>"></div><select name="status"><option value="">All statuses</option><?php foreach(['pending','approved','borrowed','returned','rejected'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=ucfirst($x)?></option><?php endforeach;?></select><button class="btn">Filter</button></form><section class="panel"><div class="print-heading"><h1>Library Borrowing Report</h1><p>Generated <?=date('F j, Y g:i A')?> · Records: <?=$rows->num_rows?></p></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Member</th><th>Book</th><th>Requested</th><th>Due</th><th>Returned</th><th>Status</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['full_name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['requested_at'])?></td><td><?=e($r['due_date']??'—')?></td><td><?=e($r['returned_at']??'—')?></td><td><?=e(ucfirst($r['status']))?></td></tr><?php endwhile;?></tbody></table></div></section><?php page_footer();?>